DROP TABLE IF EXISTS `profile_cache`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `profile_cache` (
  `user_id` int NOT NULL,
  `activity_id` int NOT NULL,
  `distance` int NOT NULL,
  `elevation` int NOT NULL,
  PRIMARY KEY (`user_id`,`activity_id`),
  KEY `IDX_B693F435A76ED395` (`user_id`),
  KEY `IDX_B693F43581C06096` (`activity_id`),
  CONSTRAINT `FK_B693F43581C06096` FOREIGN KEY (`activity_id`) REFERENCES `activity` (`id`),
  CONSTRAINT `FK_B693F435A76ED395` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

