CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `faculty_id` int NOT NULL,
  `email` varchar(180) DEFAULT NULL,
  `roles` json NOT NULL,
  `password` varchar(255) NOT NULL,
  `banned` tinyint(1) NOT NULL,
  `first_name` varchar(255) NOT NULL,
  `last_name` varchar(255) NOT NULL,
  `token` varchar(255) DEFAULT NULL,
  `password_reset_token` varchar(255) DEFAULT NULL,
  `accepted_gdpr` tinyint(1) DEFAULT NULL,
  `mailing` tinyint(1) NOT NULL DEFAULT '1',
  `email_unsubscribe_hash` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQ_8D93D649E7927C74` (`email`),
  KEY `IDX_8D93D649680CAB68` (`faculty_id`),
  KEY `email_unsubscribe_hash` (`email_unsubscribe_hash`),
  CONSTRAINT `FK_8D93D649680CAB68` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`id`),
  CONSTRAINT `user_chk_1` CHECK (json_valid(`roles`))
) ENGINE=InnoDB AUTO_INCREMENT=1914 DEFAULT CHARSET=utf8mb3;
